package main

import (
	"fmt"
	"time"
)

type feed struct {
	Name        string
	LastFetched *time.Time
}

func at(hour int) *time.Time {
	value := time.Date(2026, time.January, 1, hour, 0, 0, 0, time.UTC)
	return &value
}

func nextFeed(feeds []feed) feed {
	best := feeds[0]
	for _, candidate := range feeds[1:] {
		if candidate.LastFetched == nil && best.LastFetched != nil {
			best = candidate
			continue
		}
		if candidate.LastFetched != nil && best.LastFetched != nil && candidate.LastFetched.Before(*best.LastFetched) {
			best = candidate
		}
	}
	return best
}

func main() {
	feeds := []feed{
		{Name: "recent", LastFetched: at(12)},
		{Name: "never", LastFetched: nil},
		{Name: "old", LastFetched: at(8)},
	}
	fmt.Println(nextFeed(feeds).Name)
}

