package main

import "fmt"

type post struct {
	Title string
	URL   string
}

func uniquePosts(items []post) []post {
	seen := make(map[string]bool)
	unique := make([]post, 0, len(items))
	for _, item := range items {
		if seen[item.URL] {
			continue
		}
		seen[item.URL] = true
		unique = append(unique, item)
	}
	return unique
}

func main() {
	items := []post{
		{Title: "Go 1.25", URL: "https://go.dev/blog/go1.25"},
		{Title: "Duplicate", URL: "https://go.dev/blog/go1.25"},
		{Title: "JSON v2", URL: "https://go.dev/blog/jsonv2-exp"},
	}
	fmt.Println(len(uniquePosts(items)))
}

